from svg import box, t, arrow, line, svg

X = [23 + i * 164 for i in range(7)]
STEPS = [('1', 'Tension', 'something hurts'), ('2', 'A lens', 'it is spiritual'), ('3', 'Seeker', 'still looking'),
         ('4', 'Turning point', 'life in motion'), ('5', 'Bond inside', 'a friend in it'), ('6', 'Ties outside', 'fade or fight'),
         ('7', 'Intense time', 'days together')]
FIG = svg(1180, 310, 'Lofland and Stark: seven conditions of conversion',
          t(262, 40, 'BEFORE CONTACT', 's-t') + line(23, 52, 501, 52) + t(836, 40, 'AFTER CONTACT', 's-t') + line(515, 52, 1157, 52) +
          ''.join(box(x, 70, 150, 150, 's-box-a' if n in ('5', '7') else 's-card') + t(x + 75, 120, n, 's-t-d') +
                  t(x + 75, 162, a, 's-t-b') + t(x + 75, 190, b, 's-t-sm') for x, (n, a, b) in zip(X, STEPS)) +
          arrow(23, 248, 1150, 248) + t(590, 240, 'time', 's-t-sm') +
          t(590, 292, 'Greil and Rudy (1984), ten case studies: only 5 and 7 were present every time', 's-t-sm'))

